var n=`0088-zeama`;var t=`world-0088`;var a=`MD`;var s=`eastern-europe`;var o=4;var r=77;var l={en:`Zeamă`,ua:`Зяма`};var g={en:`A classic dish from Moldova, featuring chicken thigh, yellow onion, carrot, parsley root. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Молдова. Основні складники: куряче стегно, жовта цибуля, морква, корінь петрушки. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var m=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 60 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 60 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:60,i:[[`chicken-thigh`,650,`g`],[`water`,1500,`ml`],[`yellow-onion`,150,`g`],[`carrot`,140,`g`],[`parsley-root`,65,`g`]]},{en:`Cook the listed ingredients in simmering water for about 14 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 14 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:14,i:[[`egg-noodles`,200,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:3,i:[[`lemon-juice`,25,`ml`],[`parsley`,20,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]}];var d={slug:n,id:t,country:`MD`,region:s,servings:4,minutes:77,title:l,text:g,steps:m};export{a as country,d as default,t as id,r as minutes,s as region,o as servings,n as slug,m as steps,g as text,l as title};